def get_girth(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    girth = float('inf')
    for start_node in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start_node] = 0
        queue = [start_node]

        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    girth = min(girth, dist[u] + dist[v] + 1)
    return girth

def is_3_colorable(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def can_color(u, c):
        colors[u] = c
        for v in adj[u]:
            if colors[v] == c:
                return False
            if colors[v] == -1:
                if not can_color(v, 1 - c): # This is for 2-coloring, need to adapt for 3
                    pass
        return True

    # Backtracking for 3-coloring
    def solve(u):
        if u == n:
            return True
        for c in range(3):
            safe = True
            for v in adj[u]:
                if colors[v] == c:
                    safe = False
                    break
            if safe:
                colors[u] = c
                if solve(u + 1):
                    return True
                colors[u] = -1
        return False

    return solve(0)

